(function(){"use strict";var e=window.TD=window.TD||{};e.brand={name:"Taradhura",meaning:"tara, a star \xB7 dhura, a ridge (Kumaoni)",altitude:"2,140 m",place:"Dhura village, above Mukteshwar, Nainital district, Uttarakhand",email:"stay@taradhura.in",gstin:"05ABCDE1234F1Z9"},e.types=[{id:"deodar",name:"Deodar Room",plural:"Deodar Rooms",short:"Deodar",rooms:["D1","D2","D3","D4","D5","D6"],base:13800,size:32,sleeps:"2 + 1 child",maxAdults:2,maxKids:1,maxGuests:3,extraAdult:0,view:"Forest and garden",bed:"King or twin",line:"Six garden rooms under the old deodars, each with a wood stove and a sit-out that catches the morning.",body:"The Deodar Rooms are the quietest place on the ridge: set back among cedars that were here before the road, with a cast-iron stove that is lit for you at turndown, a reading chair at the window and a stone sit-out for the first chai. Floors are reclaimed chir pine; walls are lime-washed; the bed is dressed in hand-loomed Almora wool.",hero:"deodar-bed",ext:"deodar-ext",gallery:["deodar-bed","deodar-stove","deodar-window","deodar-forest","deodar-ext","window-forest"],captions:["Morning light in D4","The stove is lit at turndown","Snow days, February","The view from the bath","D1\u2013D6 sit under the deodars","Looking out from D2"],features:["Cast-iron wood stove","Garden sit-out","Rain shower with forest window","Hand-loomed Almora wool","Pets welcome (2 rooms)","A basket of books from the library"],pano:"deodar",panoNote:"Room D4, an afternoon in March"},{id:"ridge",name:"Ridge Cottage",plural:"Ridge Cottages",short:"Ridge",rooms:["R1","R2","R3","R4"],base:19600,size:48,sleeps:"3 adults or 2 + 2",maxAdults:3,maxKids:2,maxGuests:4,extraAdult:3e3,view:"The full range, 300 km",bed:"King + day bed",line:"Stone cottages on the lip of the ridge: a fireplace, a valley deck and the whole range from your pillow.",body:"Four stone-and-slate cottages built on the old terrace walls, angled so every bed faces Trishul. A dry-stone fireplace, a deep window seat, a cedar deck over the valley and an outdoor rain shower for the brave. In October the range is clear from 5:40 in the morning; leave the curtains open.",hero:"ridge-hearth",ext:"ridge-ext",gallery:["ridge-hearth","ridge-view","peak-alpenglow","ridge-shower","ridge-ext","range-forest"],captions:["R2, the dry-stone fireplace","The window seat at first light","Trishul from the R2 deck, 6:20 am","Outdoor rain shower, R1 and R3","Stone and slate, built on old terraces","The view from the deck"],features:["Dry-stone fireplace","Valley deck with day bed","Outdoor rain shower","Window seat facing the range","Binoculars and a peak chart","Extra bed on request"],pano:"ridge",panoNote:"Cottage R2 after dark, fire lit"},{id:"orchard",name:"Orchard House",plural:"Orchard Houses",short:"Orchard",rooms:["O1","O2"],base:32400,size:96,sleeps:"4 + 2 children",maxAdults:4,maxKids:2,maxGuests:6,extraAdult:0,view:"Apricot orchard and valley",bed:"2 bedrooms (king, twin)",line:"Two-bedroom houses in the apricot orchard, with a living room, a kitchenette and space for the grandparents.",body:"Built for families and old friends. Two bedrooms with their own baths, a long living room around a wood-burner, a kitchenette for the baby\u2019s milk at 3 am, and a deck where the apricots fall in June. The orchard has a swing, a hammock and a path to the kitchen garden that children find within an hour.",hero:"orchard-living",ext:"orchard-ext",gallery:["orchard-living","orchard-lounge","orchard-deck","balcony-mist","orchard-ext","hammock"],captions:["The long room in O1","Wood-burner and the reading corner","Dining for six","The deck in monsoon mist","O2, in the old orchard wall","The orchard hammock"],features:["Two bedrooms, two baths","Living room with wood-burner","Kitchenette","Deck in the orchard","Cot and high chair on request","Board games and a telescope"],pano:"orchard",panoNote:"The living room in O1"},{id:"star",name:"Star House",plural:"Star House",short:"Star",rooms:["S1"],base:46e3,size:74,sleeps:"2 adults",maxAdults:2,maxKids:0,maxGuests:2,extraAdult:0,view:"Range by day, the Milky Way by night",bed:"King, under a glass gable",line:"The highest house on the ridge: a glass gable over the bed, a telescope on the deck and dinner by the fire.",body:"The reason for the name. A timber A-frame at the very top of the ridge, with a glass gable over the bed so the stars are the last thing you see. A hanging fireplace, a soaking tub, a private deck with an 8-inch telescope and a star chart for the month. Dinner is served on the deck, and our naturalist will come up after dark to show you Saturn if you ask.",hero:"star-aframe",ext:"star-sky",gallery:["star-aframe","star-fire","star-cabin","telescope","star-sky","milkyway"],captions:["The glass gable at dawn","The hanging fireplace","Living and kitchen","The deck telescope","From the deck, new moon","The Milky Way rises behind the range in summer"],features:["Glass gable over the bed","Hanging fireplace","Soaking tub","8-inch telescope on the deck","Private dinner on the deck","Adults only"],pano:"star",panoNote:"The sky from the Star deck, new moon",panoSky:!0}],e.type=function(t){for(var a=0;a<e.types.length;a++)if(e.types[a].id===t)return e.types[a];return null},e.allRooms=[],e.types.forEach(function(t){t.rooms.forEach(function(a){e.allRooms.push({id:a,type:t.id})})}),e.plans=[{id:"bb",name:"Bed and breakfast",note:"Breakfast on the deck, every morning",pp:0},{id:"hb",name:"Half board",note:"Breakfast and a Kumaoni dinner",pp:2600},{id:"fb",name:"Full board",note:"Every meal, plus high tea",pp:4200}],e.pricing={gstRate:.18,weekend:1.15,occHigh:.75,occUplift:1.1,los:[{n:5,off:.15},{n:3,off:.1}],otaMarkup:1.12,prepaid:.05,deposit:.3},e.seasons=[{id:"festive",name:"Festive",from:"12-22",to:"01-02",k:1.45,minStay:3},{id:"peak-summer",name:"Summer peak",from:"04-01",to:"06-30",k:1.25,minStay:2,weekendsOnly:!0},{id:"monsoon",name:"Monsoon",from:"07-01",to:"09-30",k:.8,minStay:1},{id:"peak-autumn",name:"Clear-sky autumn",from:"10-01",to:"11-15",k:1.15,minStay:2,weekendsOnly:!0},{id:"winter",name:"Winter",from:"01-03",to:"02-28",k:.95,minStay:1},{id:"shoulder",name:"Shoulder",from:"01-01",to:"12-31",k:1,minStay:1}],e.holidays={"2026-12-25":"Christmas","2026-12-31":"New Year\u2019s Eve","2027-01-26":"Republic Day","2027-03-22":"Holi","2027-08-15":"Independence Day","2027-10-29":"Diwali","2027-12-25":"Christmas","2027-12-31":"New Year\u2019s Eve","2028-01-26":"Republic Day","2028-03-11":"Holi","2028-10-17":"Diwali"},e.addons=[{id:"kgm",name:"Kathgodam station transfer",unit:"per way",price:3800,group:"Getting here",note:"Sedan, 2 h 15 m. Driver waits with a name card.",max:2},{id:"kgm-suv",name:"Kathgodam transfer, SUV",unit:"per way",price:5200,group:"Getting here",note:"For 5\u20136 guests or lots of luggage.",max:2},{id:"pgh",name:"Pantnagar airport transfer",unit:"per way",price:5600,group:"Getting here",note:"3 h. Timed to the Delhi flight.",max:2},{id:"bird",name:"Dawn birding walk",unit:"per guest",price:2400,group:"On the ridge",note:"6:15 am, 2\xBD h, with our naturalist. Binoculars provided.",perGuest:!0,exp:"birding"},{id:"stars",name:"Stargazing session",unit:"per guest",price:1800,group:"On the ridge",note:"8-inch telescope, 90 minutes, blankets and kahwa.",perGuest:!0,exp:"stars"},{id:"cook",name:"Kumaoni cooking class",unit:"per guest",price:2200,group:"On the ridge",note:"Bhatt ki churkani, madua roti, and lunch after.",perGuest:!0,exp:"kitchen"},{id:"bonfire",name:"Bonfire and barbecue night",unit:"per stay",price:4500,group:"Evenings",note:"On your deck or the orchard lawn, up to 6 guests."},{id:"deck",name:"Private dinner on the deck",unit:"per stay",price:6500,group:"Evenings",note:"Five courses, lanterns, a server who knows when to vanish."},{id:"celebrate",name:"Celebration set-up",unit:"per stay",price:3500,group:"Evenings",note:"Buransh flowers, a cake from our kitchen, a handwritten note."},{id:"early",name:"Early check-in, 9 am",unit:"per stay",price:3e3,group:"Your stay",note:"Confirmed only if the cottage is free the night before."},{id:"late",name:"Late check-out, 2 pm",unit:"per stay",price:0,group:"Your stay",note:"Free when you book direct.",direct:!0},{id:"pet",name:"Your dog",unit:"per night",price:1500,group:"Your stay",note:"Deodar Rooms D1 and D2 only. Bed, bowls and a towel.",perNight:!0,only:["deodar"]}],e.addon=function(t){for(var a=0;a<e.addons.length;a++)if(e.addons[a].id===t)return e.addons[a];return null},e.experiences=[{id:"birding",name:"Dawn birding walk",when:"Daily",slots:["06:15"],dur:"2\xBD h",cap:6,price:2400,guide:"Naveen Joshi",level:"Easy",photo:"bird-laughingthrush",line:"Oak, rhododendron and the calls that go with them. 112 species logged from this ridge; a good morning gets you 30.",detail:"We walk the old bridle path below the ridge while the light is still low. White-throated laughingthrushes, Himalayan bulbuls, the blue flash of a verditer flycatcher, and in winter the Himalayan griffons riding the thermals off the valley. Binoculars and a field guide are in your cottage; flasks of tea come with us."},{id:"village",name:"Dhura village walk",when:"Tue \xB7 Thu \xB7 Sat",slots:["10:00"],dur:"3 h",cap:8,price:1900,guide:"Pushpa Bisht",level:"Easy to moderate",photo:"village",line:"Down through the terraces to Dhura: a farm kitchen, a temple with a 400-year-old door, and apricot jam to carry home.",detail:"Pushpa grew up in Dhura and walks you down by the stepped path the village children take to school. Tea in her aunt\u2019s kitchen, the bakhli houses with their carved doors, the terraces of madua and rajma, and the walk back up through the orchard. Ten percent of the fee goes to the village school fund."},{id:"trek",name:"Ridge trek to the cliff edge",when:"Mon \xB7 Wed \xB7 Fri \xB7 Sun",slots:["08:30"],dur:"5 h",cap:8,price:2900,guide:"Naveen Joshi",level:"Moderate",photo:"trek",line:"Eleven kilometres through oak forest to a rock ledge with a 1,500 m drop and the range all the way across.",detail:"A proper walk: 11 km out and back with 450 m of climbing, mostly in shade. We stop at the forest spring, eat a packed Kumaoni lunch on the ledge and are back for a late tea. Good shoes and a light jacket; we carry the rest."},{id:"kitchen",name:"Kumaoni kitchen",when:"Daily except Mon",slots:["11:30"],dur:"2 h + lunch",cap:6,price:2200,guide:"Chef Kamala Rawat",level:"Everyone",photo:"thali",line:"Cook bhatt ki churkani and madua roti with Kamala, then eat it on the terrace.",detail:"Kamala\u2019s kitchen garden supplies most of it. You will grind jakhiya, temper black soybeans, roll finger-millet rotis on a stone and learn why the dal is cooked in iron. Recipes are printed for you to take home."},{id:"stars",name:"Stargazing on the Star deck",when:"Nightly, weather permitting",slots:["19:30","21:00"],dur:"90 min",cap:8,price:1800,guide:"Naveen Joshi",level:"Everyone",photo:"telescope",line:"Saturn\u2019s rings, the Orion Nebula, the Andromeda galaxy, and the Milky Way with nothing in the way.",detail:"No town lights for nine kilometres, so on a moonless night the Milky Way casts a faint shadow. We use an 8-inch Dobsonian and a laser pointer, with blankets and saffron kahwa. If it clouds over we move to the library for a talk and a refund."},{id:"aipan",name:"Aipan painting",when:"Wed \xB7 Sat",slots:["15:00"],dur:"2 h",cap:10,price:1600,guide:"Pushpa Bisht",level:"Everyone",photo:"buransh",line:"The red-and-white floor art of Kumaon, painted with rice paste on geru. You take your panel home.",detail:"Aipan is drawn by Kumaoni women at thresholds and altars for festivals. Pushpa teaches the basic motifs: the lakshmi feet, the swastika border, the bel-buti. Children over seven love it."}],e.exp=function(t){for(var a=0;a<e.experiences.length;a++)if(e.experiences[a].id===t)return e.experiences[a];return null},e.venues=[{id:"lawn",name:"The Orchard Lawn",cap:"120 standing \xB7 90 seated",note:"Under the apricot trees, with the range behind the mandap."},{id:"long",name:"The Long Room",cap:"40 seated \xB7 60 standing",note:"Our dining room: a 14 m table, two fireplaces, glass on three sides."},{id:"deck",name:"The Ridge Deck",cap:"24 seated",note:"For sundowners, sangeet rehearsals and the speech nobody forgets."},{id:"library",name:"The Library",cap:"16 boardroom \xB7 24 theatre",note:"Screen, whiteboard wall, fire, and nobody else\u2019s meeting next door."}],e.posts=[{id:"reading-the-range",title:"Reading the range: which peak is which",kicker:"Field notes",date:"2026-10-28",read:7,photo:"range-dusk",author:"Naveen Joshi, naturalist",dek:"From the Ridge Cottages you can see about 300 km of Himalaya. Here is how to name what you are looking at.",body:["On a clear October morning the range runs the whole width of the window, from the Gangotri peaks in the far west to the Panchachuli massif on the Nepal border. Most guests ask the same question on the first morning, usually with a cup in hand: which one is Nanda Devi?","Start with the trident. Trishul is the long, three-pointed ridge a little left of centre, and it turns pink first because its western face catches the earliest light. Count right from its last point and the next big shape is the double summit of Nanda Devi, at 7,816 m the highest mountain entirely in India. Her eastern summit is the sharper one; locals call the pair the two sisters.","Further right, Nanda Kot is the rounded snow dome, the one that looks like a pillow. Then, almost on the right-hand edge of the view, the five fingers of Panchachuli, which in the legend are the five cooking hearths of the Pandavas on their last journey.","The light tells you the time better than a clock. Pink on Trishul is about 22 minutes before sunrise. When the pink reaches Panchachuli, chai should be at your door. In the evening it runs the other way: the range goes amber, then rose, then a cold blue-white that holds for six or seven minutes after the valley is dark.","There is a brass peak chart on every Ridge Cottage deck, cut from a photograph taken from R2. If the range is hiding, come and find me in the library; I keep the photographs from every clear morning since 2019."]},{id:"buransh-fortnight",title:"The fortnight the buransh blooms",kicker:"Seasons",date:"2026-03-21",read:5,photo:"buransh",author:"Kamala Rawat, head chef",dek:"For two weeks in March the hillside goes red, and the kitchen goes slightly mad.",body:["Buransh is the tree rhododendron, the state tree of Uttarakhand, and in the second half of March it turns the slope below the Ridge Cottages the colour of a temple sari. The flowers are edible, faintly sour, and we use all of them.","The first ones go into sherbet, the bright red drink you will be handed on arrival. Then chutney with jaggery and roasted cumin, which we serve with the breakfast parathas. Then a buransh jelly for the high tea, and, if the bloom is generous, a small batch of buransh wine that only the staff are allowed to judge.","We pick only from the lower branches, and never more than a third of a tree. The rest is for the bulbuls and the sunbirds, who are louder about it than we are.","If you want to see it, aim for the last ten days of March. Nights are still cold, around 4\xB0C, so the stoves stay lit. Days are bright and the range is usually clear until noon."]},{id:"apricot-june",title:"Apricot season in Dhura",kicker:"The village",date:"2026-06-14",read:6,photo:"apples",author:"Pushpa Bisht, village walks",dek:"June is when the orchards pay for the year. A morning with the families who grow our fruit.",body:["Dhura has grown apricots, plums and apples for as long as anyone can remember, on terraces cut into the slope a hundred years before the road arrived. In June the apricots come all at once, and every family in the village is up a tree by six.","We buy from eleven families. The best fruit goes into the crates for the Haldwani market; the bruised and the very ripe come to our kitchen for jam, chutney and the apricot tart that sells out at dinner.","On the Tuesday and Saturday village walks in June you can pick with us. Bring a cloth bag. Mrs Bisht at the top house will insist you take more than you can carry, and you should let her."]},{id:"birds-from-the-deck",title:"A birder\u2019s list: 112 species from one deck",kicker:"Field notes",date:"2026-09-02",read:8,photo:"bird-bulbul",author:"Naveen Joshi, naturalist",dek:"Six years of morning counts from the Long Room deck, and the eight birds most guests see on their first walk.",body:["Since 2020 we have kept a morning count from the deck of the Long Room: fifteen minutes, every day, written into a ledger by whoever is on breakfast. The list now stands at 112 species.","The eight you are most likely to see: the white-throated laughingthrush (in noisy gangs), the Himalayan bulbul with its swept-back crest, the great barbet (heard long before it is seen), the grey-hooded warbler, the blue whistling thrush on the stream, the verditer flycatcher, the black-headed jay, and in winter, the Himalayan griffon, a vulture with a wingspan wider than the dining table.","The rarities are worth waking for. A koklass pheasant has crossed the orchard twice. A pair of Himalayan cutias nested in the oaks below R3 in 2024. Every few winters a wallcreeper turns up on the stone of the lodge itself, which is the closest thing to a holiday our naturalists get.","The dawn walk leaves at 6:15. Binoculars are in your cottage."]},{id:"kitchen-garden",title:"The kitchen garden, month by month",kicker:"How we run things",date:"2026-08-10",read:5,photo:"balcony-mist",author:"Kamala Rawat, head chef",dek:"Half of what you eat here grows on four terraces below the Long Room. What comes up when.",body:["The garden is four old terraces below the Long Room, about a third of an acre, worked by Govind and whoever from the kitchen is free after breakfast. It feeds the resort for most of the year.","March and April are for greens: mustard, spinach, fenugreek and the first lettuces, plus the buransh from the slope. May brings peas, beans and the herb beds. In the monsoon we grow what the rain wants: cucumber, pumpkin, the local gourds, and corn that we roast at the bonfire.","Autumn is the best season in the garden and the kitchen: rajma and bhatt from the village, potatoes, radish, and chillies drying on the roof of the Long Room. Winter is roots and stored grain, and the jams we made in June.","Guests are welcome in the garden any morning. If you want to pick for your own dinner, tell the kitchen by noon and Govind will meet you there at four."]},{id:"monsoon",title:"Monsoon on the ridge: the case for July",kicker:"Seasons",date:"2026-07-08",read:5,photo:"mist-forest",author:"The owners",dek:"Rates are 20% lower and the forest is at its greenest. What to expect, honestly.",body:["Most people come in October for the clear range, and they are right. But July and August have their own case. The forest is impossibly green, the mist moves through the cottages like a guest, and the ridge is quiet enough to hear the stream at the bottom of the valley.","You will not see the range every day. Mornings are often clear until about nine; afternoons bring rain that is more drama than inconvenience. Leeches exist on the lower trail in August, and we will lend you socks for them.","Monsoon rates are 20% lower, cancellations are free up to 7 days before arrival, and the kitchen has its best produce of the year: wild mushrooms, fresh rajma and the first corn."]}],e.post=function(t){for(var a=0;a<e.posts.length;a++)if(e.posts[a].id===t)return e.posts[a];return null},e.templates=[{id:"confirm",name:"Booking confirmed",when:"On booking",body:"Namaste {first}, your {type} is confirmed for {checkin} to {checkout} ({nights}). Reference {ref}. We will write a week before with directions and the weather. \u2014 The Taradhura front desk"},{id:"prearrival",name:"Pre-arrival: a week out",when:"7 days before",body:"Namaste {first}, you are with us from {checkin}. Nights are around {low}\xB0C this month, so bring a warm layer. Would you like a Kathgodam transfer? Reply with your train and we will arrange it. Your arrival time on file: {arrival}."},{id:"directions",name:"Directions and the last 9 km",when:"2 days before",body:"Namaste {first}, the last 9 km after Mukteshwar are narrow but fully tarred. Phone signal drops for about 4 km after the Dhura temple; that is normal. Look for the stone gate with the brass star. We will have chai ready."},{id:"weather",name:"Weather note",when:"As needed",body:"Namaste {first}, a short note on the weather: {note}. Your plans are safe with us; if anything changes we will call."},{id:"checkout",name:"Thank you, after check-out",when:"Day after",body:"Thank you for staying with us, {first}. If you have a moment, tell us one thing we should keep and one we should change. Your next stay booked direct includes a free night in the monsoon."}]})();
